            continue
        self_d = abs(tx - nx) + abs(ty - ny)
        opp_d = abs(tx - ox) + abs(ty - oy)

        # reward immediate pickup / proximity; also prevent paths opening behind obstacles
        pickup = 1 if (nx, ny) == (tx, ty) else 0
        # if another resource is closer, account for it
        best_adv = -10**18
